/**
 * @fileoverview 32-Bit HD Pixel Art Illustration Sprite Atlas (Auto-Generated)
 * Contains transparent PNG sprite sheets for all 4 medieval factions x 9 unit classes.
 */
(function (global) {
  'use strict';
  const CELL_SIZE = 168;
  const CELL_MAP = {
    KING:     { row: 0, col: 0 },
    QUEEN:    { row: 0, col: 1 },
    ROOK:     { row: 0, col: 2 },
    GUARD:    { row: 0, col: 2 },
    CHARIOT:  { row: 1, col: 0 },
    CANNON:   { row: 1, col: 1 },
    HORSE:    { row: 1, col: 2 },
    KNIGHT:   { row: 1, col: 2 },
    ELEPHANT: { row: 2, col: 0 },
    BISHOP:   { row: 2, col: 1 },
    SOLDIER:  { row: 2, col: 2 },
    PAWN:     { row: 2, col: 2 }
  };
  const ATLAS_URLS = {"GORYEO": "data:image/png;base64,", "TEMPLAR": "data:image/png;base64,", "BYZANTINE": "data:image/png;base64,", "MAMLUK": "data:image/png;base64,"};
  const images = {};
  const loaded = {};

  function ensureLoaded() {
    if (typeof Image === 'undefined') return;
    for (const fac of Object.keys(ATLAS_URLS)) {
      if (!images[fac]) {
        const img = new Image();
        img.onload = function () { loaded[fac] = true; };
        img.src = ATLAS_URLS[fac];
        images[fac] = img;
        if (img.complete && img.naturalWidth > 0) loaded[fac] = true;
      }
    }
  }
  ensureLoaded();

  global.HDSpriteAtlas = {
    CELL_SIZE,
    CELL_MAP,
    isReady(faction) {
      ensureLoaded();
      const img = images[faction];
      return Boolean(img && (loaded[faction] || (img.complete && img.naturalWidth > 0)));
    },
    getImage(faction) {
      ensureLoaded();
      return images[faction] || null;
    },
    getCellRect(type) {
      const m = CELL_MAP[type] || CELL_MAP.SOLDIER;
      return {
        sx: m.col * CELL_SIZE,
        sy: m.row * CELL_SIZE,
        sw: CELL_SIZE,
        sh: CELL_SIZE
      };
    }
  };
})(typeof window !== 'undefined' ? window : globalThis);
